parameters.jsCode:
// Collect all tool IDs and prepare for assistant update
const items = $input.all();
const toolIds = [];
const toolDetails = {};

// Extract tool IDs from all tool creation responses
for (let i = 2; i < items.length; i++) {
  const item = items[i];
  if (item.json && item.json.id) {
    toolIds.push(item.json.id);

    // Store tool details for reference
    const toolName = item.json.function?.name || `tool_${i-1}`;
    toolDetails[toolName] = {
      id: item.json.id,
      name: toolName,
      description: item.json.function?.description || 'Custom tool'
    };
  }
}

// Get setup data
const setupData = items[0].json;
const assistantData = items[1].json;

console.log('All tool IDs collected:', toolIds);
console.log('Tool details:', toolDetails);

return [{
  json: {
    assistant_id: assistantData?.id,
    tool_ids: toolIds,
    tool_count: toolIds.length,
    tools_created: toolDetails,
    setup_config: {
      server_url: setupData['Server URL'],
      organization_name: setupData['Organization Name'],
      contact_email: setupData['Contact Email'],
      client_id: setupData['Client ID']
    },
    integration_endpoints: {
      hubspot: `${setupData['Server URL']}/custom-tools/execute/hubspot_integration`,
      email: `${setupData['Server URL']}/custom-tools/execute/email_notification`,
      search: `${setupData['Server URL']}/custom-tools/execute/web_search`,
      database: `${setupData['Server URL']}/custom-tools/execute/database_storage`,
      calendar: `${setupData['Server URL']}/custom-tools/execute/calendar_scheduling`
    }
  }
}];

